+@namespace sv_29a3f455777d4ed3bdb95f0bf374c4e1.Components.Pages.Apply
+
+<nav class="step-indicator" aria-label="Application progress">
+    <ol class="step-list">
+        @for (int i = 0; i < StepNames.Count; i++)
+        {
+            var stepIndex = i;
+            var status = GetStepStatus(stepIndex);
+            <li class="step-item @status" @onclick="() => OnStepClick(stepIndex)" role="button" tabindex="0">
+                <span class="step-badge">
+                    @if (status == "completed")
+                    {
+                        <span>&#10003;</span>
+                    }
+                    else
+                    {
+                        @(stepIndex + 1)
+                    }
+                </span>
+                <span class="step-label">@StepNames[stepIndex]</span>
+            </li>
+        }
+    </ol>
+</nav>
+
+@code {
+    [Parameter, EditorRequired] public int CurrentStep { get; set; }
+    [Parameter, EditorRequired] public EventCallback<int> OnStepSelected { get; set; }
+
+    private static readonly List<string> StepNames = new()
+    {
+        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
+    };
+
+    private string GetStepStatus(int index)
+    {
+        if (index == CurrentStep) return "active";
+        if (index < CurrentStep) return "completed";
+        return "future";
+    }
+
+    private async Task OnStepClick(int index)
+    {
+        if (index < CurrentStep)
+        {
+            await OnStepSelected.InvokeAsync(index);
+        }
+    }
+}
+

