{"file_text": "@page "/apply"
@rendermode InteractiveServer
@namespace sv_29a3f455777d4ed3bdb95f0bf374c4e1.Components.Pages.Apply
@using sv_29a3f455777d4ed3bdb95f0bf374c4e1.Models

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="_currentStep" OnStepSelected="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep
                FullName="@_fullName"
                Email="@_email"
                Phone="@_phone"
                Address="@_address"
                ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="HandlePersonalInfoNext" />
            break;

        case 1:
            <WorkHistoryStep
                Entries="_workEntries"
                OnNext="HandleWorkHistoryNext"
                OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep
                References="_references"
                OnNext="HandleReferencesNext"
                OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep
                CoverLetter="@_coverLetter"
                OnNext="HandleCoverLetterNext"
                OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep
                FullName="@_fullName"
                Email="@_email"
                Phone="@_phone"
                Address="@_address"
                WorkEntries="_workEntries"
                References="_references"
                CoverLetter="@_coverLetter"
                OnBack="GoBack"
                OnEditStep="GoToStep"
                OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private List<WorkHistoryStep.WorkEntryModel> _workEntries = new() { new() };
    private List<ReferencesStep.ReferenceModel> _references = new() { new(), new() };
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private void GoBack()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private void HandlePersonalInfoNext((string FullName, string Email, string Phone, string Address) data)
    {
        _fullName = data.FullName;
        _email = data.Email;
        _phone = data.Phone;
        _address = data.Address;
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkHistoryStep.WorkEntryModel> entries)
    {
        _workEntries = entries;
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> references)
    {
        _references = references;
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _currentStep = 4;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            new PersonalInfo(_fullName, _email, _phone, _address),
            new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
            _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            _coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}
