toolArgs.file_text:
.apply-page {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1.5rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
    position: relative;
}

.step-list::before {
    content: '';
    position: absolute;
    top: 18px;
    left: 10%;
    right: 10%;
    height: 2px;
    background: #ddd;
    z-index: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    z-index: 1;
    cursor: default;
    flex: 1;
}

.step-item.completed {
    cursor: pointer;
}

.step-badge {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.875rem;
    background: #e0e0e0;
    color: #888;
    transition: all 0.2s;
}

.step-item.active .step-badge {
    background: #4361ee;
    color: white;
    box-shadow: 0 2px 8px rgba(67, 97, 238, 0.3);
}

.step-item.completed .step-badge {
    background: #2ecc71;
    color: white;
}

.step-item.future .step-badge {
    background: #e0e0e0;
    color: #aaa;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #666;
    max-width: 80px;
}

.step-item.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #2ecc71;
}

.step-item.future .step-label {
    color: #aaa;
}

/* Step Content */
.step-content {
    background: white;
    border: 1px solid #e0e0e0;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.step-description {
    color: #666;
    margin-bottom: 1.5rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.375rem;
    font-weight: 500;
    color: #333;
    font-size: 0.875rem;
}

.form-control {
    width: 100%;
    padding: 0.625rem 0.875rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 0.9375rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
    font-weight: 400 !important;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #eee;
}

.btn {
    padding: 0.625rem 1.5rem;
    border-radius: 6px;
    font-size: 0.9375rem;
    font-weight: 500;
    cursor: pointer;
    border: none;
    transition: all 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #4361ee;
    color: white;
    margin-left: auto;
}

.btn-primary:hover:not(:disabled) {
    background: #3651d4;
}

.btn-outline {
    background: transparent;
    border: 1px solid #ddd;
    color: #555;
}

.btn-outline:hover {
    background: #f5f5f5;
}

.btn-secondary {
    background: #f0f0f0;
    color: #333;
    border: 1px dashed #ccc;
    width: 100%;
    padding: 0.75rem;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #e8e8e8;
}

.btn-danger-sm {
    background: transparent;
    border: 1px solid #e74c3c;
    color: #e74c3c;
    padding: 0.25rem 0.75rem;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
}

.btn-danger-sm:hover {
    background: #e74c3c;
    color: white;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    font-size: 0.875rem;
    text-decoration: underline;
}

.btn-link:hover {
    color: #3651d4;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1rem;
}

/* Validation */
.validation-summary {
    background: #fef0f0;
    border: 1px solid #f5c6cb;
    color: #c0392b;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-top: 1rem;
    font-size: 0.875rem;
}

.field-error {
    color: #c0392b;
    font-size: 0.8rem;
    margin-top: 0.25rem;
    display: block;
}

/* Work Entry & Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.work-entry-header,
.reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h4,
.reference-header h4 {
    margin: 0;
    color: #333;
}

/* Cover Letter */
.cover-letter-textarea {
    resize: vertical;
    min-height: 200px;
    font-family: inherit;
}

.char-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.375rem;
}

/* Review Step */
.review-section {
    border-bottom: 1px solid #eee;
    padding-bottom: 1.25rem;
    margin-bottom: 1.25rem;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1.1rem;
    color: #1a1a2e;
}

.review-data {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.5rem;
    margin: 0;
}

.review-data dt {
    font-weight: 500;
    color: #666;
}

.review-data dd {
    margin: 0;
    color: #333;
}

.review-work-entry {
    margin-bottom: 1rem;
    padding-left: 1rem;
    border-left: 3px solid #4361ee;
}

.review-dates {
    font-size: 0.85rem;
    color: #666;
}

.review-description {
    margin-top: 0.5rem;
    color: #555;
    font-size: 0.9rem;
}

.review-reference {
    margin-bottom: 0.75rem;
    padding-left: 1rem;
    border-left: 3px solid #2ecc71;
}

.review-cover-letter {
    white-space: pre-wrap;
    background: #f9f9f9;
    padding: 1rem;
    border-radius: 6px;
    font-size: 0.9rem;
    line-height: 1.6;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.submission-confirmation h3 {
    color: #2ecc71;
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.submission-confirmation p {
    font-size: 1.1rem;
    color: #555;
}

/* Responsive */
@media (max-width: 600px) {
    .form-row {
        grid-template-columns: 1fr;
    }

    .step-label {
        font-size: 0.65rem;
    }

    .step-badge {
        width: 30px;
        height: 30px;
        font-size: 0.75rem;
    }
}

